-- Add examples to the 26 original N5 starter grammar records.
-- The newer 100-set curriculum is expanded separately; these older published
-- records remain in the catalogue and also need five examples each.
begin;
do $expand_n5_legacy_examples$
declare
  v_examples jsonb := $legacy_n5_examples$[{"pattern":"N は","additional_examples":[{"japanese":"私は毎日日本語を勉強します。","romaji":"Watashi wa mainichi nihongo o benkyou shimasu.","meaning":"I study Japanese every day."},{"japanese":"父は会社で働きます。","romaji":"Chichi wa kaisha de hatarakimasu.","meaning":"My father works at a company."},{"japanese":"今日は日曜日です。","romaji":"Kyou wa nichiyoubi desu.","meaning":"Today is Sunday."}]},{"pattern":"N が","additional_examples":[{"japanese":"鈴木さんが来ます。","romaji":"Suzuki-san ga kimasu.","meaning":"Suzuki is coming."},{"japanese":"ここに駅があります。","romaji":"Koko ni eki ga arimasu.","meaning":"There is a station here."},{"japanese":"鳥が空を飛んでいます。","romaji":"Tori ga sora o tonde imasu.","meaning":"A bird is flying in the sky."}]},{"pattern":"N を V","additional_examples":[{"japanese":"毎朝水を飲みます。","romaji":"Maiasa mizu o nomimasu.","meaning":"I drink water every morning."},{"japanese":"妹は新聞を読みます。","romaji":"Imouto wa shinbun o yomimasu.","meaning":"My younger sister reads the newspaper."},{"japanese":"昼ご飯を作ります。","romaji":"Hirugohan o tsukurimasu.","meaning":"I make lunch."}]},{"pattern":"Place に 行きます","additional_examples":[{"japanese":"毎朝七時に起きます。","romaji":"Maiasa shichi-ji ni okimasu.","meaning":"I get up at seven every morning."},{"japanese":"日曜日に友達に会います。","romaji":"Nichiyoubi ni tomodachi ni aimasu.","meaning":"I meet my friend on Sunday."},{"japanese":"来週学校に行きます。","romaji":"Raishuu gakkou ni ikimasu.","meaning":"I will go to school next week."}]},{"pattern":"Place で V","additional_examples":[{"japanese":"学校で日本語を勉強します。","romaji":"Gakkou de nihongo o benkyou shimasu.","meaning":"I study Japanese at school."},{"japanese":"店でパンを買います。","romaji":"Mise de pan o kaimasu.","meaning":"I buy bread at the shop."},{"japanese":"公園で写真を撮ります。","romaji":"Kouen de shashin o torimasu.","meaning":"I take pictures in the park."}]},{"pattern":"N1 の N2","additional_examples":[{"japanese":"これは兄の時計です。","romaji":"Kore wa ani no tokei desu.","meaning":"This is my older brother's watch."},{"japanese":"母の名前はゆみです。","romaji":"Haha no namae wa Yumi desu.","meaning":"My mother's name is Yumi."},{"japanese":"あれは日本語の本です。","romaji":"Are wa nihongo no hon desu.","meaning":"That is a Japanese book."}]},{"pattern":"Place へ 行きます","additional_examples":[{"japanese":"毎日学校へ行きます。","romaji":"Mainichi gakkou e ikimasu.","meaning":"I go to school every day."},{"japanese":"来月日本へ帰ります。","romaji":"Raigetsu Nihon e kaerimasu.","meaning":"I will return to Japan next month."},{"japanese":"友達は駅へ走ります。","romaji":"Tomodachi wa eki e hashirimasu.","meaning":"My friend runs toward the station."}]},{"pattern":"N と N","additional_examples":[{"japanese":"朝ご飯にパンと卵を食べます。","romaji":"Asagohan ni pan to tamago o tabemasu.","meaning":"I eat bread and eggs for breakfast."},{"japanese":"机の上に本と鉛筆があります。","romaji":"Tsukue no ue ni hon to enpitsu ga arimasu.","meaning":"There is a book and a pencil on the desk."},{"japanese":"土曜日と日曜日は休みです。","romaji":"Doyoubi to nichiyoubi wa yasumi desu.","meaning":"Saturday and Sunday are days off."}]},{"pattern":"N も ...","additional_examples":[{"japanese":"兄も日本語を勉強します。","romaji":"Ani mo nihongo o benkyou shimasu.","meaning":"My older brother also studies Japanese."},{"japanese":"私もコーヒーを飲みます。","romaji":"Watashi mo koohii o nomimasu.","meaning":"I drink coffee too."},{"japanese":"今日は母も家にいます。","romaji":"Kyou wa haha mo ie ni imasu.","meaning":"My mother is also at home today."}]},{"pattern":"N / な-adjective です","additional_examples":[{"japanese":"田中さんは医者です。","romaji":"Tanaka-san wa isha desu.","meaning":"Tanaka is a doctor."},{"japanese":"あの人は日本人です。","romaji":"Ano hito wa nihonjin desu.","meaning":"That person is Japanese."},{"japanese":"この町は静かです。","romaji":"Kono machi wa shizuka desu.","meaning":"This town is quiet."}]},{"pattern":"N じゃありません","additional_examples":[{"japanese":"今日は休みじゃありません。","romaji":"Kyou wa yasumi ja arimasen.","meaning":"Today is not a day off."},{"japanese":"田中さんは先生じゃありません。","romaji":"Tanaka-san wa sensei ja arimasen.","meaning":"Tanaka is not a teacher."},{"japanese":"これは私のかばんじゃありません。","romaji":"Kore wa watashi no kaban ja arimasen.","meaning":"This is not my bag."}]},{"pattern":"Sentence か","additional_examples":[{"japanese":"あなたは学生ですか。","romaji":"Anata wa gakusei desu ka.","meaning":"Are you a student?"},{"japanese":"明日は雨ですか。","romaji":"Ashita wa ame desu ka.","meaning":"Will it rain tomorrow?"},{"japanese":"それは日本の本ですか。","romaji":"Sore wa Nihon no hon desu ka.","meaning":"Is that a book from Japan?"}]},{"pattern":"N でした","additional_examples":[{"japanese":"昨日は月曜日でした。","romaji":"Kinou wa getsuyoubi deshita.","meaning":"Yesterday was Monday."},{"japanese":"あの人は先生でした。","romaji":"Ano hito wa sensei deshita.","meaning":"That person was a teacher."},{"japanese":"先週はとても忙しい日でした。","romaji":"Senshuu wa totemo isogashii hi deshita.","meaning":"Last week was a very busy week."}]},{"pattern":"Verb stem + ます","additional_examples":[{"japanese":"土曜日にスーパーへ行きます。","romaji":"Doyoubi ni suupaa e ikimasu.","meaning":"I go to the supermarket on Saturday."},{"japanese":"母は料理を作ります。","romaji":"Haha wa ryouri o tsukurimasu.","meaning":"My mother cooks."},{"japanese":"毎晩本を読みます。","romaji":"Maiban hon o yomimasu.","meaning":"I read a book every evening."}]},{"pattern":"Verb stem + ません","additional_examples":[{"japanese":"日曜日は働きません。","romaji":"Nichiyoubi wa hatarakimasen.","meaning":"I do not work on Sundays."},{"japanese":"朝はコーヒーを飲みません。","romaji":"Asa wa koohii o nomimasen.","meaning":"I do not drink coffee in the morning."},{"japanese":"今日はテレビを見ません。","romaji":"Kyou wa terebi o mimasen.","meaning":"I will not watch television today."}]},{"pattern":"Verb stem + ました","additional_examples":[{"japanese":"昨日友達に会いました。","romaji":"Kinou tomodachi ni aimashita.","meaning":"I met my friend yesterday."},{"japanese":"昼ご飯にうどんを食べました。","romaji":"Hirugohan ni udon o tabemashita.","meaning":"I ate udon for lunch."},{"japanese":"新しい本を買いました。","romaji":"Atarashii hon o kaimashita.","meaning":"I bought a new book."}]},{"pattern":"Verb stem + ませんでした","additional_examples":[{"japanese":"昨日は勉強しませんでした。","romaji":"Kinou wa benkyou shimasen deshita.","meaning":"I did not study yesterday."},{"japanese":"朝ご飯を食べませんでした。","romaji":"Asagohan o tabemasen deshita.","meaning":"I did not eat breakfast."},{"japanese":"友達は来ませんでした。","romaji":"Tomodachi wa kimasen deshita.","meaning":"My friend did not come."}]},{"pattern":"Thing が あります / Person が います","additional_examples":[{"japanese":"部屋に机があります。","romaji":"Heya ni tsukue ga arimasu.","meaning":"There is a desk in the room."},{"japanese":"公園に子どもがいます。","romaji":"Kouen ni kodomo ga imasu.","meaning":"There are children in the park."},{"japanese":"かばんの中に財布があります。","romaji":"Kaban no naka ni saifu ga arimasu.","meaning":"There is a wallet inside the bag."}]},{"pattern":"Remove い + かったです","additional_examples":[{"japanese":"旅行は楽しかったです。","romaji":"Ryokou wa tanoshikatta desu.","meaning":"The trip was enjoyable."},{"japanese":"昨日のテストは難しかったです。","romaji":"Kinou no tesuto wa muzukashikatta desu.","meaning":"Yesterday's test was difficult."},{"japanese":"その店の料理はおいしかったです。","romaji":"Sono mise no ryouri wa oishikatta desu.","meaning":"The food at that restaurant was delicious."}]},{"pattern":"Verb stem + たいです","additional_examples":[{"japanese":"新しい自転車を買いたいです。","romaji":"Atarashii jitensha o kaitai desu.","meaning":"I want to buy a new bicycle."},{"japanese":"日本で写真を撮りたいです。","romaji":"Nihon de shashin o toritai desu.","meaning":"I want to take pictures in Japan."},{"japanese":"週末は友達に会いたいです。","romaji":"Shuumatsu wa tomodachi ni aitai desu.","meaning":"I want to meet my friend on the weekend."}]},{"pattern":"V-て + ください","additional_examples":[{"japanese":"ここで待ってください。","romaji":"Koko de matte kudasai.","meaning":"Please wait here."},{"japanese":"名前をもう一度書いてください。","romaji":"Namae o mou ichido kaite kudasai.","meaning":"Please write your name one more time."},{"japanese":"ゆっくり読んでください。","romaji":"Yukkuri yonde kudasai.","meaning":"Please read slowly."}]},{"pattern":"V-てもいいです","additional_examples":[{"japanese":"このペンを使ってもいいですか。","romaji":"Kono pen o tsukatte mo ii desu ka.","meaning":"May I use this pen?"},{"japanese":"窓を開けてもいいですか。","romaji":"Mado o akete mo ii desu ka.","meaning":"May I open the window?"},{"japanese":"ここにかばんを置いてもいいですか。","romaji":"Koko ni kaban o oite mo ii desu ka.","meaning":"May I put my bag here?"}]},{"pattern":"V-てはいけません","additional_examples":[{"japanese":"ここで写真を撮ってはいけません。","romaji":"Koko de shashin o totte wa ikemasen.","meaning":"You must not take pictures here."},{"japanese":"この部屋に入ってはいけません。","romaji":"Kono heya ni haitte wa ikemasen.","meaning":"You must not enter this room."},{"japanese":"学校で走ってはいけません。","romaji":"Gakkou de hashitte wa ikemasen.","meaning":"You must not run at school."}]},{"pattern":"Reason + から","additional_examples":[{"japanese":"今日は寒いですから、家にいます。","romaji":"Kyou wa samui desu kara, ie ni imasu.","meaning":"Because it is cold today, I will stay home."},{"japanese":"明日はテストですから、勉強します。","romaji":"Ashita wa tesuto desu kara, benkyou shimasu.","meaning":"Because there is a test tomorrow, I will study."},{"japanese":"忙しいですから、後で電話します。","romaji":"Isogashii desu kara, ato de denwa shimasu.","meaning":"Because I am busy, I will call later."}]},{"pattern":"A は B より adjective","additional_examples":[{"japanese":"電車はバスより速いです。","romaji":"Densha wa basu yori hayai desu.","meaning":"Trains are faster than buses."},{"japanese":"夏は冬より暑いです。","romaji":"Natsu wa fuyu yori atsui desu.","meaning":"Summer is hotter than winter."},{"japanese":"このかばんはあのかばんより大きいです。","romaji":"Kono kaban wa ano kaban yori ookii desu.","meaning":"This bag is bigger than that bag."}]},{"pattern":"Number + ぐらい","additional_examples":[{"japanese":"駅まで十分ぐらいかかります。","romaji":"Eki made juppun gurai kakarimasu.","meaning":"It takes about ten minutes to the station."},{"japanese":"毎日二時間ぐらい勉強します。","romaji":"Mainichi ni-jikan gurai benkyou shimasu.","meaning":"I study for about two hours every day."},{"japanese":"家族は五人ぐらいです。","romaji":"Kazoku wa go-nin gurai desu.","meaning":"There are about five people in my family."}]}]$legacy_n5_examples$::jsonb;
  v_updated integer;
begin
  update public.grammar_points as grammar
  set examples = coalesce(grammar.examples, '[]'::jsonb) || item.additional_examples
  from jsonb_to_recordset(v_examples) as item(
    pattern text,
    additional_examples jsonb
  )
  where grammar.jlpt_level::text = 'N5'
    and grammar.publication_status::text = 'published'
    and grammar.pattern = item.pattern;

  get diagnostics v_updated = row_count;
  if v_updated <> 26 then
    raise exception 'Expected to expand 26 legacy N5 grammar sets, updated %', v_updated;
  end if;
end;
$expand_n5_legacy_examples$;
commit;
